template.script:
(function(){if(window.albErr)return;
window.albErr=function(msg){var old=document.querySelector('.alb-fv-ov.vf-e');if(old)old.remove();
var ov=document.createElement('div');ov.className='alb-fv-ov vf-e';ov.setAttribute('role','dialog');ov.setAttribute('aria-modal','true');
ov.innerHTML='<div class="alb-fv-box"><div class="alb-fv-hd"><span class="alb-fv-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5.5M12 16.5v.01"/></svg></span><b>تنبيه</b><button type="button" class="alb-fv-x" aria-label="إغلاق"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg></button></div><div class="alb-fv-bd"><div class="alb-fv-txt"></div></div><div class="alb-fv-ft"><button type="button" class="alb-fv-go">حسناً</button></div></div>';
ov.querySelector('.alb-fv-txt').textContent=msg;
function close(){ov.classList.remove('on');setTimeout(function(){ov.remove()},250);document.removeEventListener('keydown',key,true);var b=document.querySelector('#formwrap .vf-f.bad');if(b){b.scrollIntoView({behavior:'smooth',block:'center'});var i=b.querySelector('input,textarea');if(i)setTimeout(function(){try{i.focus({preventScroll:true})}catch(e){}},450)}else if(!document.getElementById('vf-consent').checked){var c=document.querySelector('#formwrap .vf-consent');c.scrollIntoView({behavior:'smooth',block:'center'})}}
function key(e){if(e.key==='Escape'){e.preventDefault();close()}}
ov.querySelector('.alb-fv-x').onclick=close;ov.querySelector('.alb-fv-go').onclick=close;ov.addEventListener('click',function(e){if(e.target===ov)close()});document.addEventListener('keydown',key,true);
document.body.appendChild(ov);requestAnimationFrame(function(){ov.classList.add('on')});};})();

(function(){
const KEY='alb-visaform-v2';try{localStorage.removeItem('alb-visaform-v1');}catch(_){}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const W=document.getElementById('formwrap');
/* ---------- state ---------- */
function val(k){const els=$$('[data-k="'+k+'"]');if(!els.length)return '';const e=els[0];
 if(e.type==='radio'){const c=els.find(x=>x.checked);return c?c.value:'';}
 if(e.type==='checkbox'){return els.filter(x=>x.checked).map(x=>x.value);}
 return (e.value||'').trim();}
function collect(){const o={};$$('[data-k]').forEach(e=>{const k=e.dataset.k;if(e.type==='radio'){if(e.checked)o[k]=e.value;}else if(e.type==='checkbox'){o[k]=o[k]||[];if(e.checked)o[k].push(e.value);}else o[k]=e.value;});return o;}
function restore(){try{const o=JSON.parse(localStorage.getItem(KEY)||'null');if(!o)return;$$('[data-k]').forEach(e=>{const v=o[e.dataset.k];if(v===undefined)return;if(e.type==='radio')e.checked=(e.value===v);else if(e.type==='checkbox')e.checked=Array.isArray(v)&&v.includes(e.value);else e.value=v;});}catch(_){}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(collect()));}catch(_){}}
/* ---------- conditional blocks + progress ---------- */
function sw(){$$('.vf-sw[data-sw]').forEach(d=>{const [k,v]=d.dataset.sw.split('=');const cur=val(k);const on=Array.isArray(cur)?cur.includes(v):cur===v;d.classList.toggle('on',on);});}
function prog(){const req=$$('[data-k][required]');let done=0;req.forEach(e=>{if((e.value||'').trim())done++;});const extra=[['f8',val('f8')],['f9',val('f9')],['f12',val('f12')],['f18',val('f18')],['f21',val('f21').length],['f24',val('f24')],['f26',val('f26')],['f27',val('f27')],['f33',val('f33')]];extra.forEach(([k,v])=>{if(v)done++;});const tot=req.length+extra.length;const p=Math.round(done/tot*100);$('#vf-pct').textContent=p+'%';$('#vf-bar').style.width=p+'%';$('#vf-left').textContent=p===100?'اكتملت الحقول الأساسية':(tot-done)+' حقلًا أساسيًا متبقيًا';}
function fmt(d){return d.getDate().toString().padStart(2,'0')+'-'+(d.getMonth()+1).toString().padStart(2,'0')+'-'+d.getFullYear();}
function pd(s){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');return m?new Date(+m[1],+m[2]-1,+m[3]):null;}
function addM(d,n){const x=new Date(d);x.setMonth(x.getMonth()+n);return x;}
function warn(id,msg,ok){const e=$('#'+id);if(!e)return;e.textContent=msg||'';e.classList.toggle('on',!!msg);e.classList.toggle('ok',!!ok);}
let HARD={};
function checks(){HARD={};const today=new Date();today.setHours(0,0,0,0);
 const iss=pd(val('f14')),exp=pd(val('f15')),arr=pd(val('f29')),dep=pd(val('f30'));
 /* issue date: within 10 years */
 if(iss){const lim=new Date(today);lim.setFullYear(lim.getFullYear()-10);if(iss>today){warn('w14','تاريخ الإصدار لا يمكن أن يكون في المستقبل.');HARD.f14=1;}else if(iss<lim){warn('w14','الجواز صادر منذ أكثر من 10 سنوات ('+fmt(iss)+') – لا تقبله دول الشنغن ولو كان ساري المفعول. يلزم جواز جديد.');HARD.f14=1;}else warn('w14','');}else warn('w14','');
 /* expiry: >= departure + 3 months */
 if(exp){const base=dep||addM(today,0);const need=addM(base,3);
  if(exp<today){warn('w15','الجواز منتهي الصلاحية ('+fmt(exp)+').');HARD.f15=1;}
  else if(exp<need){warn('w15','صلاحية الجواز غير كافية: يجب أن تمتد 3 أشهر على الأقل بعد تاريخ المغادرة'+(dep?' ('+fmt(dep)+')':' المتوقع')+'، أي حتى '+fmt(need)+' على الأقل، بينما ينتهي جوازك في '+fmt(exp)+'.');HARD.f15=1;}
  else warn('w15','صلاحية الجواز كافية ✓ (مطلوب حتى '+fmt(need)+' على الأقل).',true);}else warn('w15','');
 /* duration */
 const f25=$('[data-k=f25]');
 if(arr&&dep){if(dep<arr){warn('w30','تاريخ المغادرة قبل تاريخ الوصول.');HARD.f30=1;}else{warn('w30','');const days=Math.round((dep-arr)/86400000)+1;if(!f25.dataset.manual||!f25.value)f25.value=days;}}else warn('w30','');
 const n=parseInt(f25.value||'0',10);
 if(n>90){warn('w25','الحد الأقصى لتأشيرة الشنغن قصيرة الإقامة 90 يومًا خلال أي 180 يومًا – المدة المدخلة ('+n+' يومًا) غير مقبولة.');HARD.f25=1;}
 else if(arr&&dep&&n&&n!==Math.round((dep-arr)/86400000)+1){warn('w25','ملاحظة: المدة لا تطابق تاريخي الوصول والمغادرة ('+(Math.round((dep-arr)/86400000)+1)+' يومًا).');}
 else warn('w25','');
}
$('[data-k=f25]').addEventListener('input',e=>{e.target.dataset.manual=e.target.value?'1':'';});
function consentUI(){$('#vf-preview').disabled=!$('#vf-consent').checked;}
$('#vf-consent').addEventListener('change',consentUI);
W.addEventListener('input',()=>{sw();checks();prog();save();});W.addEventListener('change',()=>{sw();checks();prog();save();});
restore();sw();checks();prog();consentUI();
/* ---------- validation ---------- */
function validate(){let ok=true,first=null;$$('.vf-f').forEach(f=>f.classList.remove('bad'));
 $$('[data-k][required]').forEach(e=>{if(!(e.value||'').trim()){ok=false;const f=e.closest('.vf-f');f.classList.add('bad');if(!f.querySelector('.vf-err')){const d=document.createElement('div');d.className='vf-err';d.textContent='هذا الحقل مطلوب';f.appendChild(d);}first=first||f;}});
 const need=f=>{if(!f.querySelector(':scope>.vf-err')){const d=document.createElement('div');d.className='vf-err';d.textContent='يرجى اختيار أحد الخيارات';f.appendChild(d);}};
 [['f8','input[name=f8]'],['f9','input[name=f9]'],['f12','input[name=f12]'],['f18','input[name=f18]'],['f24','input[name=f24]'],['f26','input[name=f26]'],['f27','input[name=f27]'],['f33','input[name=f33]']].forEach(([k,sel])=>{if(!val(k)){ok=false;const f=$(sel).closest('.vf-f');f.classList.add('bad');need(f);first=first||f;}});
 if(!val('f21').length){ok=false;const f=$('[data-k=f21]').closest('.vf-f');f.classList.add('bad');first=first||f;}
 Object.keys(HARD).forEach(k=>{ok=false;const f=$('[data-k='+k+']').closest('.vf-f');f.classList.add('bad');first=first||f;});
 if(!$('#vf-consent').checked){ok=false;if(window.albErr)albErr('يرجى تأكيد صحة البيانات (مربع الموافقة) قبل المتابعة.');else alert('يرجى تأكيد صحة البيانات قبل المتابعة.');}
 else if(!ok){const m=Object.keys(HARD).length?'يوجد شرط غير مستوفى (صلاحية الجواز أو مدة الإقامة) – راجع التنبيه باللون الأحمر.':'يرجى تعبئة الحقول الأساسية المحددة باللون الأحمر.';if(window.albErr)albErr(m);else alert(m);}
 if(first)first.scrollIntoView({behavior:'smooth',block:'center'});return ok;}
/* ---------- text helpers ---------- */
const MAP={'Á':'A','À':'A','Â':'A','Ä':'A','Ã':'A','Å':'A','Č':'C','Ç':'C','Ď':'D','É':'E','È':'E','Ê':'E','Ë':'E','Ě':'E','Í':'I','Ì':'I','Î':'I','Ï':'I','Ň':'N','Ñ':'N','Ó':'O','Ò':'O','Ô':'O','Ö':'O','Õ':'O','Ř':'R','Š':'S','Ť':'T','Ú':'U','Ù':'U','Û':'U','Ü':'U','Ů':'U','Ý':'Y','Ž':'Z','á':'a','à':'a','â':'a','ä':'a','ã':'a','å':'a','č':'c','ç':'c','ď':'d','é':'e','è':'e','ê':'e','ë':'e','ě':'e','í':'i','ì':'i','î':'i','ï':'i','ň':'n','ñ':'n','ó':'o','ò':'o','ô':'o','ö':'o','õ':'o','ř':'r','š':'s','ť':'t','ú':'u','ù':'u','û':'u','ü':'u','ů':'u','ý':'y','ž':'z','–':'-','—':'-','’':"'",'‘':"'",'“':'"','”':'"','…':'...','٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9'};
function lat(s){s=String(s||'');let o='';for(const ch of s){if(MAP[ch]!==undefined)o+=MAP[ch];else if(ch.charCodeAt(0)<128||/[\u00A0-\u00FF]/.test(ch))o+=ch;else o+='?';}return o.replace(/\?+/g,'').replace(/[ \t]+/g,' ').trim();}
function up(s){return lat(s).split(/(\s+)/).map(t=>t.includes('@')?t.toLowerCase():t.toUpperCase()).join('');}
function dmy(s){if(!s)return '';const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s);return m?m[3]+'-'+m[2]+'-'+m[1]:lat(s);}
/* ---------- PDF ---------- */
let PDFCACHE=null;
async function build(){
 const {PDFDocument,StandardFonts,rgb}=PDFLib;
 if(!PDFCACHE){const r=await fetch('__PDF_URL__');PDFCACHE=await r.arrayBuffer();}
 const doc=await PDFDocument.load(PDFCACHE.slice(0));
 const font=await doc.embedFont(StandardFonts.Helvetica), bold=await doc.embedFont(StandardFonts.HelveticaBold);
 const P=doc.getPages(); const H=842; const ink=rgb(.05,.1,.35);
 function wrap(txt,size,maxW){const out=[];for(const part of String(txt).split(/\n+/)){if(!part.trim())continue;let cur='';for(const w of part.trim().split(/\s+/)){const t=cur?cur+' '+w:w;if(font.widthOfTextAtSize(t,size)<=maxW||!cur)cur=t;else{out.push(cur);cur=w;}}if(cur)out.push(cur);}return out;}
 function T(pg,x,ytop,txt,size,maxW,maxLines){txt=String(txt||'').trim();if(!txt)return;size=size||9;const page=P[pg];
  if(!maxW){page.drawText(txt.replace(/\n+/g,' '),{x,y:H-ytop-size*0.78,size,font,color:ink});return;}
  const L=maxLines||1;let s=size,lines=wrap(txt,s,maxW);
  while(lines.length>L&&s>5.5){s-=.5;lines=wrap(txt,s,maxW);}
  lines.slice(0,L).forEach((ln,i)=>page.drawText(ln,{x,y:H-ytop-s*0.78-i*(s+1.6),size:s,font,color:ink}));}
 function TL(pg,x,ytop,txt,size,maxW,maxLines){T(pg,x,ytop,txt,size,maxW,maxLines||3);}
 function X(pg,x,ytop){P[pg].drawText('X',{x:x+1.6,y:H-ytop-8.6,size:9,font:bold,color:ink});}
 const v=k=>val(k);
 /* ---- page 1 ---- */
 T(0,60,171,up(v('f1')),9,345);T(0,60,203,up(v('f2')),9,345);T(0,60,238,up(v('f3')),9,345);
 T(0,60,276,dmy(v('f4')),9,110);T(0,194,273,up(v('f5')),9,90);T(0,194,296,up(v('f6')),9,90);
 T(0,301,281,up(v('f7')),8,112);T(0,301,291,up(v('f7b')),7,112);
 if(v('f8')==='M')X(0,58.2,321.6);if(v('f8')==='F')X(0,97.4,321.6);
 ({single:[243.1,321.6],married:[279.2,321.6],separated:[320.8,321.6],divorced:[367.9,321.6],widow:[243.1,339.9],other:[292.9,339.9]})[v('f9')]&&X(0,...({single:[243.1,321.6],married:[279.2,321.6],separated:[320.8,321.6],divorced:[367.9,321.6],widow:[243.1,339.9],other:[292.9,339.9]})[v('f9')]);
 if(v('f9')==='other')T(0,302,353,up(v('f9o')),7,105);
 TL(0,60,397,up(v('f10')),7.5,345,2);
 T(0,205,420,up(v('f11')),9,200);
 ({ordinary:[59.6,450.7],diplomatic:[130.9,450.7],service:[209.3,450.7],official:[275.6,450.7],special:[342.8,450.7],other:[59.6,469.1]})[v('f12')]&&X(0,...({ordinary:[59.6,450.7],diplomatic:[130.9,450.7],service:[209.3,450.7],official:[275.6,450.7],special:[342.8,450.7],other:[59.6,469.1]})[v('f12')]);
 if(v('f12')==='other')T(0,203,472,up(v('f12o')),7.5,205);
 T(0,60,497,up(v('f13')),9,115);T(0,194,497,dmy(v('f14')),9,62);T(0,276,497,dmy(v('f15')),9,62);T(0,357,497,up(v('f16')),7.5,55,2);
 TL(0,60,531,up(v('f17')),7.5,232,3);T(0,300,531,lat(v('f17t')),8.5,108,2);
 if(v('f18')==='yes'){X(0,99.2,572.3);if(v('f18p'))X(0,139.3,572.3);T(0,256,574,up(v('f18p')),7.5,148);T(0,168,594,up(v('f18n')),8,102);T(0,315,594,dmy(v('f18v')),8,88);}else X(0,59.6,572.3);
 T(0,135,617,up(v('f19')),9,275);
 TL(0,60,657,up(v('f20')),7.5,348,3);
 const PUR={tourism:[59.6,709.1],business:[111,709.1],family:[161.2,709.1],cultural:[264.4,709.1],sports:[312.2,709.1],official:[356.4,709.1],medical:[59.6,727.4],study:[133.7,727.4],transit:[173.9,727.4],airport:[218.3,727.4],other:[285.6,727.4]};
 v('f21').forEach(k=>PUR[k]&&X(0,...PUR[k]));if(v('f21').includes('other'))T(0,297,741,up(v('f21o')),7,115);
 /* ---- page 2 ---- */
 T(1,60,67,up(v('f22')),9,190);T(1,268,67,up(v('f23')),9,140);
 ({single:[59.6,98.3],two:[120.2,98.3],multiple:[179.9,98.3]})[v('f24')]&&X(1,...({single:[59.6,98.3],two:[120.2,98.3],multiple:[179.9,98.3]})[v('f24')]);
 T(1,350,93,lat(v('f25'))?lat(v('f25'))+' DAYS':'',9,60);
 if(v('f26')==='yes'){X(1,59.6,210.3);if(v('f26a')||v('f26b'))X(1,85.7,210.3);T(1,180,213,dmy(v('f26a')),8,85);T(1,282,213,dmy(v('f26b')),8,120);}else X(1,59.6,192);
 if(v('f27')==='yes'){X(1,211.2,252.7);T(1,278,266,dmy(v('f27d')),8,125);}else X(1,59.6,252.7);
 T(1,97,303,up(v('f28i')),7.5,95);T(1,236,303,dmy(v('f28a')),7.5,60);T(1,317,303,dmy(v('f28b')),7.5,88);
 T(1,60,329,dmy(v('f29')),9,160);T(1,249,329,dmy(v('f30')),9,160);
 T(1,60,368,up(v('f31')),9.5,348,2);TL(1,48,437,up(v('f31a')),7.5,235,3);T(1,290,437,lat(v('f31t')),8,118,2);
 TL(1,48,467,up(v('f32')),7.5,235,3);T(1,290,476,lat(v('f32t')),8,118,2);TL(1,48,518,up(v('f32c')),7.5,360,3);
 if(v('f33')==='self'){X(1,59.6,591.8);const M={cash:[58.8,628.7],tc:[58.8,647],cc:[58.8,665.4],acc:[58.8,683.9],tr:[58.8,702.2],other:[58.8,720.6]};v('f33s').forEach(k=>M[k]&&X(1,...M[k]));if(v('f33s').includes('other'))T(1,73,741,up(v('f33so')),7,68);}
 else{X(1,193.8,591.8);if(v('f33k')==='other'){X(1,193.8,628.7);T(1,278,631,up(v('f33ko')),7,128);}else X(1,193.8,610.2);const M={cash:[193.8,665.4],acc:[193.8,683.9],all:[193.8,702.2],tr:[193.8,720.6],other:[193.8,739.1]};v('f33p').forEach(k=>M[k]&&X(1,...M[k]));if(v('f33p').includes('other'))T(1,278,741,up(v('f33po')),7,128);}
 /* ---- page 3 ---- */
 T(2,48,83.5,up(v('f34s')),7.5,205);T(2,264,83.5,up(v('f34f')),7.5,250);T(2,48,105,dmy(v('f34d')),9,90);T(2,147,105,up(v('f34n')),9,108);T(2,264,105,up(v('f34p')),9,250);
 ({spouse:[59.6,137.6],child:[103.2,137.6],grandchild:[140.9,137.6],dependent:[196.7,137.6]})[v('f35')]&&X(2,...({spouse:[59.6,137.6],child:[103.2,137.6],grandchild:[140.9,137.6],dependent:[196.7,137.6]})[v('f35')]);
 const pd=[up(v('f36p')),dmy(v('f36d'))].filter(Boolean).join(', ');
 T(2,60,176,pd,9,180);T(2,48,632,pd,9,200);
 doc.setTitle('Application for Schengen Visa – '+up(v('f1'))+' '+up(v('f3')));doc.setAuthor('Alburaihi');
 return await doc.save();
}
let LASTURL=null;
function fname(){return 'Schengen-Visa-Application-'+(up(val('f1'))||'FORM').replace(/[^A-Z0-9]+/g,'_')+'.pdf';}
function busy(on){$$('.pvbar .btn').forEach(b=>b.disabled=on);document.body.style.cursor=on?'progress':'';}
async function renderPages(bytes){const box=$('#vf-pages');box.innerHTML='<div class="ld">جاري تجهيز الاستمارة…</div>';
 if(!window.pdfjsLib){box.innerHTML='<div class="ld">تعذّرت المعاينة – استخدم «حفظ كملف PDF».</div>';return;}
 pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
 const doc=await pdfjsLib.getDocument({data:bytes.slice(0),standardFontDataUrl:'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/standard_fonts/',disableFontFace:true}).promise;box.innerHTML='';
 const cssW=Math.min(900,box.clientWidth||900),ratio=Math.min(2,window.devicePixelRatio||1);
 for(let i=1;i<=doc.numPages;i++){const pg=await doc.getPage(i);const v0=pg.getViewport({scale:1});const sc=cssW/v0.width*ratio;const vp=pg.getViewport({scale:sc});const c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;c.style.width=cssW+'px';box.appendChild(c);await pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;}}
let LASTBYTES=null;
window.vfEdit=function(){document.body.classList.remove('pv');$('#pvwrap').classList.remove('on');const y=$('#formwrap').getBoundingClientRect().top+window.scrollY-90;window.scrollTo({top:Math.max(0,y),behavior:'smooth'});};
window.vfRun=async function(mode){if(!validate())return;busy(true);try{const bytes=await build();LASTBYTES=bytes;const blob=new Blob([bytes],{type:'application/pdf'});if(LASTURL)URL.revokeObjectURL(LASTURL);LASTURL=URL.createObjectURL(blob);const url=LASTURL;
 if(mode==='preview'){document.body.classList.add('pv');$('#pvwrap').classList.add('on');const y=$('#pvwrap').getBoundingClientRect().top+window.scrollY-90;window.scrollTo({top:Math.max(0,y),behavior:'smooth'});await renderPages(bytes);}
 else if(mode==='download'){dl(blob);}
 else if(mode==='print'){const f=document.createElement('iframe');f.style.cssText='position:fixed;width:0;height:0;border:0;opacity:0';f.setAttribute('data-alb-noguard','1');f.src=url;document.body.appendChild(f);f.onload=()=>{setTimeout(()=>{const h=document.documentElement,had=h.classList.contains('alb-owner');h.classList.add('alb-owner');try{f.contentWindow.focus();f.contentWindow.print();}catch(e){window.open(url,'_blank');}finally{setTimeout(()=>{if(!had)h.classList.remove('alb-owner')},1500);}},400);};}
 else if(mode==='share'||mode==='share2'){const file=new File([blob],fname(),{type:'application/pdf'});const msg='استمارة تأشيرة الشنغن – '+up(val('f1'))+' '+up(val('f3'));
  if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:'Schengen Visa Application',text:msg});}catch(e){}}
  else{dl(blob);if(mode==='share')setTimeout(()=>window.open('https://wa.me/420776666688?text='+encodeURIComponent(msg+'\n(تم تنزيل ملف PDF على جهازي وسأرفقه هنا)'),'_blank','noopener'),600);else if(window.albErr)albErr('تم تنزيل ملف PDF – أرفقه في التطبيق الذي تريد المشاركة عبره.');}}
 }catch(e){console.error(e);if(window.albErr)albErr('تعذّر إنشاء ملف PDF. حدّث الصفحة وحاول مجددًا.');else alert('تعذّر إنشاء ملف PDF.');}finally{busy(false);}};
function dl(blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fname();document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},2000);}
function doReset(){try{localStorage.removeItem(KEY);}catch(_){}
 $$('[data-k]').forEach(e=>{if(e.type==='radio'||e.type==='checkbox')e.checked=e.defaultChecked;else{e.value=e.defaultValue;delete e.dataset.manual;}});
 $('#vf-consent').checked=false;$$('.vf-f.bad').forEach(f=>f.classList.remove('bad'));$$('.vf-warn').forEach(w=>{w.textContent='';w.classList.remove('on','ok');});
 consentUI();document.body.classList.remove('pv');$('#pvwrap').classList.remove('on');sw();checks();prog();
