window.vfReset=function(){
 if(!document.getElementById('vf-dlg-css')){const st=document.createElement('style');st.id='vf-dlg-css';st.textContent='.vfd-ov{position:fixed;inset:0;z-index:2147483000;background:rgba(15,10,6,.58);backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:18px;opacity:0;transition:opacity .2s;direction:rtl}.vfd-ov.on{opacity:1}.vfd-card{width:100%;max-width:420px;background:#fffdf8;color:#241f16;border:1px solid #eadfce;border-radius:22px;box-shadow:0 24px 60px rgba(0,0,0,.4);padding:26px 24px 20px;text-align:center;font-family:Cairo,Tajawal,sans-serif;transform:translateY(14px) scale(.97);transition:transform .25s}.vfd-ov.on .vfd-card{transform:none}html:not(.alb-light) .vfd-card{background:#1f1b17;color:#f3ead9;border-color:#3a3026}.vfd-ic{width:64px;height:64px;border-radius:50%;margin:0 auto 12px;display:flex;align-items:center;justify-content:center;background:#fdeceb;color:#c62828}html:not(.alb-light) .vfd-ic{background:#3b1f1a}.vfd-ic svg{width:30px;height:30px}.vfd-card h3{margin:0 0 8px;font-size:19px;font-weight:800}.vfd-card p{margin:0 0 16px;font-size:15px;line-height:1.7;color:#6b5b55;font-family:Tajawal,sans-serif}html:not(.alb-light) .vfd-card p{color:#d8ccc7}.vfd-acts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.vfd-acts button{text-align:center;justify-content:center;display:inline-flex;align-items:center;width:100%;padding:12px;border-radius:12px;border:1px solid #d8cdbc;background:#fff;color:#3a2622;font:700 15px Cairo,Tajawal,sans-serif;cursor:pointer;transition:.15s}.vfd-acts button.yes{background:#c62828;border-color:#c62828;color:#fff}.vfd-acts button.yes:hover{background:#a81f1f}.vfd-acts button:hover{filter:brightness(.97)}html:not(.alb-light) .vfd-acts button{background:#2a2220;border-color:#4a3c38;color:#eee}';document.head.appendChild(st);}
