function close(){ov.classList.remove('on');setTimeout(function(){ov.remove()},250);document.removeEventListener('keydown',key,true);var b=document.querySelector('#formwrap .vf-f.bad');if(b){b.scrollIntoView({behavior:'smooth',block:'center'});var i=b.querySelector('input,textarea');if(i)setTimeout(function(){try{i.focus({preventScroll:true})}catch(e){}},450)}else if(!document.getElementById('vf-consent').checked){var c=document.querySelector('#formwrap .vf-consent');c.scrollIntoView({behavior:'smooth',block:'center'})}}
