(function(){
const KEY='alb-visaform-v2';try{localStorage.removeItem('alb-visaform-v1');}catch(_){}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const W=document.getElementById('formwrap');
/* ---------- state ---------- */
function val(k){const els=$$('[data-k="'+k+'"]');if(!els.length)return '';const e=els[0];
 if(e.type==='radio'){const c=els.find(x=>x.checked);return c?c.value:'';}
 if(e.type==='checkbox'){return els.filter(x=>x.checked).map(x=>x.value);}
 return (e.value||'').trim();}
function collect(){const o={};$$('[data-k]').forEach(e=>{const k=e.dataset.k;if(e.type==='radio'){if(e.checked)o[k]=e.value;}else if(e.type==='checkbox'){o[k]=o[k]||[];if(e.checked)o[k].push(e.value);}else o[k]=e.value;});return o;}
function restore(){try{const o=JSON.parse(localStorage.getItem(KEY)||'null');if(!o)return;$$('[data-k]').forEach(e=>{const v=o[e.dataset.k];if(v===undefined)return;if(e.type==='radio')e.checked=(e.value===v);else if(e.type==='checkbox')e.checked=Array.isArray(v)&&v.includes(e.value);else e.value=v;});}catch(_){}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(collect()));}catch(_){}}
/* ---------- conditional blocks + progress ---------- */
function sw(){$$('.vf-sw[data-sw]').forEach(d=>{const [k,v]=d.dataset.sw.split('=');const cur=val(k);const on=Array.isArray(cur)?cur.includes(v):cur===v;d.classList.toggle('on',on);});}
function prog(){const req=$$('[data-k][required]');let done=0;req.forEach(e=>{if((e.value||'').trim())done++;});const extra=[['f8',val('f8')],['f9',val('f9')],['f12',val('f12')],['f18',val('f18')],['f21',val('f21').length],['f24',val('f24')],['f26',val('f26')],['f27',val('f27')],['f33',val('f33')]];extra.forEach(([k,v])=>{if(v)done++;});const tot=req.length+extra.length;const p=Math.round(done/tot*100);$('#vf-pct').textContent=p+'%';$('#vf-bar').style.width=p+'%';$('#vf-left').textContent=p===100?'اكتملت الحقول الأساسية':(tot-done)+' حقلًا أساسيًا متبقيًا';}
function fmt(d){return d.getDate().toString().padStart(2,'0')+'-'+(d.getMonth()+1).toString().padStart(2,'0')+'-'+d.getFullYear();}
function pd(s){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');return m?new Date(+m[1],+m[2]-1,+m[3]):null;}
function addM(d,n){const x=new Date(d);x.setMonth(x.getMonth()+n);return x;}
function warn(id,msg,ok){const e=$('#'+id);if(!e)return;e.textContent=msg||'';e.classList.toggle('on',!!msg);e.classList.toggle('ok',!!ok);}
let HARD={};
function checks(){HARD={};const today=new Date();today.setHours(0,0,0,0);
 const iss=pd(val('f14')),exp=pd(val('f15')),arr=pd(val('f29')),dep=pd(val('f30'));
 /* issue date: within 10 years */
 if(iss){const lim=new Date(today);lim.setFullYear(lim.getFullYear()-10);if(iss>today){warn('w14','تاريخ الإصدار لا يمكن أن يكون في المستقبل.');HARD.f14=1;}else if(iss<lim){warn('w14','الجواز صادر منذ أكثر من 10 سنوات ('+fmt(iss)+') – لا تقبله دول الشنغن ولو كان ساري المفعول. يلزم جواز جديد.');HARD.f14=1;}else warn('w14','');}else warn('w14','');
 /* expiry: >= departure + 3 months */
 if(exp){const base=dep||addM(today,0);const need=addM(base,3);
  if(exp<today){warn('w15','الجواز منتهي الصلاحية ('+fmt(exp)+').');HARD.f15=1;}
  else if(exp<need){warn('w15','صلاحية الجواز غير كافية: يجب أن تمتد 3 أشهر على الأقل بعد تاريخ المغادرة'+(dep?' ('+fmt(dep)+')':' المتوقع')+'، أي حتى '+fmt(need)+' على الأقل، بينما ينتهي جوازك في '+fmt(exp)+'.');HARD.f15=1;}
  else warn('w15','صلاحية الجواز كافية ✓ (مطلوب حتى '+fmt(need)+' على الأقل).',true);}else warn('w15','');
 /* duration */
 const f25=$('[data-k=f25]');
 if(arr&&dep){if(dep<arr){warn('w30','تاريخ المغادرة قبل تاريخ الوصول.');HARD.f30=1;}else{warn('w30','');const days=Math.round((dep-arr)/86400000)+1;if(!f25.dataset.manual||!f25.value)f25.value=days;}}else warn('w30','');
 const n=parseInt(f25.value||'0',10);
 if(n>90){warn('w25','الحد الأقصى لتأشيرة الشنغن قصيرة الإقامة 90 يومًا خلال أي 180 يومًا – المدة المدخلة ('+n+' يومًا) غير مقبولة.');HARD.f25=1;}
 else if(arr&&dep&&n&&n!==Math.round((dep-arr)/86400000)+1){warn('w25','ملاحظة: المدة لا تطابق تاريخي الوصول والمغادرة ('+(Math.round((dep-arr)/86400000)+1)+' يومًا).');}
 else warn('w25','');
}
$('[data-k=f25]').addEventListener('input',e=>{e.target.dataset.manual=e.target.value?'1':'';});
