/* ---------- validation ---------- */
function validate(){let ok=true,first=null;$$('.vf-f').forEach(f=>f.classList.remove('bad'));
 $$('[data-k][required]').forEach(e=>{if(!(e.value||'').trim()){ok=false;const f=e.closest('.vf-f');f.classList.add('bad');if(!f.querySelector('.vf-err')){const d=document.createElement('div');d.className='vf-err';d.textContent='هذا الحقل مطلوب';f.appendChild(d);}first=first||f;}});
 const need=f=>{if(!f.querySelector(':scope>.vf-err')){const d=document.createElement('div');d.className='vf-err';d.textContent='يرجى اختيار أحد الخيارات';f.appendChild(d);}};
 [['f8','input[name=f8]'],['f9','input[name=f9]'],['f12','input[name=f12]'],['f18','input[name=f18]'],['f24','input[name=f24]'],['f26','input[name=f26]'],['f27','input[name=f27]'],['f33','input[name=f33]']].forEach(([k,sel])=>{if(!val(k)){ok=false;const f=$(sel).closest('.vf-f');f.classList.add('bad');need(f);first=first||f;}});
 if(!val('f21').length){ok=false;const f=$('[data-k=f21]').closest('.vf-f');f.classList.add('bad');first=first||f;}
 Object.keys(HARD).forEach(k=>{ok=false;const f=$('[data-k='+k+']').closest('.vf-f');f.classList.add('bad');first=first||f;});
 if(!$('#vf-consent').checked){ok=false;if(window.albErr)albErr('يرجى تأكيد صحة البيانات (مربع الموافقة) قبل المتابعة.');else alert('يرجى تأكيد صحة البيانات قبل المتابعة.');}
 else if(!ok){const m=Object.keys(HARD).length?'يوجد شرط غير مستوفى (صلاحية الجواز أو مدة الإقامة) – راجع التنبيه باللون الأحمر.':'يرجى تعبئة الحقول الأساسية المحددة باللون الأحمر.';if(window.albErr)albErr(m);else alert(m);}
 if(first)first.scrollIntoView({behavior:'smooth',block:'center'});return ok;}
/* ---------- text helpers ---------- */
const MAP={'Á':'A','À':'A','Â':'A','Ä':'A','Ã':'A','Å':'A','Č':'C','Ç':'C','Ď':'D','É':'E','È':'E','Ê':'E','Ë':'E','Ě':'E','Í':'I','Ì':'I','Î':'I','Ï':'I','Ň':'N','Ñ':'N','Ó':'O','Ò':'O','Ô':'O','Ö':'O','Õ':'O','Ř':'R','Š':'S','Ť':'T','Ú':'U','Ù':'U','Û':'U','Ü':'U','Ů':'U','Ý':'Y','Ž':'Z','á':'a','à':'a','â':'a','ä':'a','ã':'a','å':'a','č':'c','ç':'c','ď':'d','é':'e','è':'e','ê':'e','ë':'e','ě':'e','í':'i','ì':'i','î':'i','ï':'i','ň':'n','ñ':'n','ó':'o','ò':'o','ô':'o','ö':'o','õ':'o','ř':'r','š':'s','ť':'t','ú':'u','ù':'u','û':'u','ü':'u','ů':'u','ý':'y','ž':'z','–':'-','—':'-','’':"'",'‘':"'",'“':'"','”':'"','…':'...','٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9'};
function lat(s){s=String(s||'');let o='';for(const ch of s){if(MAP[ch]!==undefined)o+=MAP[ch];else if(ch.charCodeAt(0)<128||/[\u00A0-\u00FF]/.test(ch))o+=ch;else o+='?';}return o.replace(/\?+/g,'').replace(/[ \t]+/g,' ').trim();}
function up(s){return lat(s).split(/(\s+)/).map(t=>t.includes('@')?t.toLowerCase():t.toUpperCase()).join('');}
function dmy(s){if(!s)return '';const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s);return m?m[3]+'-'+m[2]+'-'+m[1]:lat(s);}
/* ---------- PDF ---------- */
let PDFCACHE=null;
async function build(){
 const {PDFDocument,StandardFonts,rgb}=PDFLib;
 if(!PDFCACHE){const r=await fetch('__PDF_URL__');PDFCACHE=await r.arrayBuffer();}
 const doc=await PDFDocument.load(PDFCACHE.slice(0));
 const font=await doc.embedFont(StandardFonts.Helvetica), bold=await doc.embedFont(StandardFonts.HelveticaBold);
 const P=doc.getPages(); const H=842; const ink=rgb(.05,.1,.35);
 function wrap(txt,size,maxW){const out=[];for(const part of String(txt).split(/\n+/)){if(!part.trim())continue;let cur='';for(const w of part.trim().split(/\s+/)){const t=cur?cur+' '+w:w;if(font.widthOfTextAtSize(t,size)<=maxW||!cur)cur=t;else{out.push(cur);cur=w;}}if(cur)out.push(cur);}return out;}
