 ({single:[243.1,321.6],married:[279.2,321.6],separated:[320.8,321.6],divorced:[367.9,321.6],widow:[243.1,339.9],other:[292.9,339.9]})[v('f9')]&&X(0,...({single:[243.1,321.6],married:[279.2,321.6],separated:[320.8,321.6],divorced:[367.9,321.6],widow:[243.1,339.9],other:[292.9,339.9]})[v('f9')]);
