 ({ordinary:[59.6,450.7],diplomatic:[130.9,450.7],service:[209.3,450.7],official:[275.6,450.7],special:[342.8,450.7],other:[59.6,469.1]})[v('f12')]&&X(0,...({ordinary:[59.6,450.7],diplomatic:[130.9,450.7],service:[209.3,450.7],official:[275.6,450.7],special:[342.8,450.7],other:[59.6,469.1]})[v('f12')]);
 if(v('f12')==='other')T(0,203,472,up(v('f12o')),7.5,205);
