 TL(0,60,531,up(v('f17')),7.5,232,3);T(0,300,531,lat(v('f17t')),8.5,108,2);
 if(v('f18')==='yes'){X(0,99.2,572.3);if(v('f18p'))X(0,139.3,572.3);T(0,256,574,up(v('f18p')),7.5,148);T(0,168,594,up(v('f18n')),8,102);T(0,315,594,dmy(v('f18v')),8,88);}else X(0,59.6,572.3);
 T(0,135,617,up(v('f19')),9,275);
 TL(0,60,657,up(v('f20')),7.5,348,3);
 const PUR={tourism:[59.6,709.1],business:[111,709.1],family:[161.2,709.1],cultural:[264.4,709.1],sports:[312.2,709.1],official:[356.4,709.1],medical:[59.6,727.4],study:[133.7,727.4],transit:[173.9,727.4],airport:[218.3,727.4],other:[285.6,727.4]};
 v('f21').forEach(k=>PUR[k]&&X(0,...PUR[k]));if(v('f21').includes('other'))T(0,297,741,up(v('f21o')),7,115);
