 T(1,60,67,up(v('f22')),9,190);T(1,268,67,up(v('f23')),9,140);
 ({single:[59.6,98.3],two:[120.2,98.3],multiple:[179.9,98.3]})[v('f24')]&&X(1,...({single:[59.6,98.3],two:[120.2,98.3],multiple:[179.9,98.3]})[v('f24')]);
