 if(v('f26')==='yes'){X(1,59.6,210.3);if(v('f26a')||v('f26b'))X(1,85.7,210.3);T(1,180,213,dmy(v('f26a')),8,85);T(1,282,213,dmy(v('f26b')),8,120);}else X(1,59.6,192);
