function busy(on){$$('.pvbar .btn').forEach(b=>b.disabled=on);document.body.style.cursor=on?'progress':'';}
async function renderPages(bytes){const box=$('#vf-pages');box.innerHTML='<div class="ld">جاري تجهيز الاستمارة…</div>';
 if(!window.pdfjsLib){box.innerHTML='<div class="ld">تعذّرت المعاينة – استخدم «حفظ كملف PDF».</div>';return;}
 pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
 const doc=await pdfjsLib.getDocument({data:bytes.slice(0),standardFontDataUrl:'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/standard_fonts/',disableFontFace:true}).promise;box.innerHTML='';
 const cssW=Math.min(900,box.clientWidth||900),ratio=Math.min(2,window.devicePixelRatio||1);
 for(let i=1;i<=doc.numPages;i++){const pg=await doc.getPage(i);const v0=pg.getViewport({scale:1});const sc=cssW/v0.width*ratio;const vp=pg.getViewport({scale:sc});const c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;c.style.width=cssW+'px';box.appendChild(c);await pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;}}
